- Simple API surface for a reusable component

## Code Example
```javascript
import React, {useEffect, useState} from 'react';
import {FlatList, Text, View, ActivityIndicator, RefreshControl} from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';

export function NewsList({endpoint}) {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);

  const load = async (ep) => {
    try {
      const res = await fetch(ep);
      const json = await res.json();
      setData(json.articles || []);
      await AsyncStorage.setItem('news_cache', JSON.stringify(json.articles || []));
    } catch (e) {
      const cached = await AsyncStorage.getItem('news_cache');
      if (cached) setData(JSON.parse(cached));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(endpoint); }, [endpoint]);

  const onRefresh = async () => {
    setRefreshing(true);
    await load(endpoint);
    setRefreshing(false);
  };

  if (loading) return <ActivityIndicator />;
  return (
    <FlatList
      data={data}
      keyExtractor={(i, idx) => idx.toString()}
      renderItem={({item}) => <Text>{item.title}</Text>}
      refreshControl={<RefreshControl refreshing={refreshing} onRefresh={onRefresh} />}
    />
  );
}
```

